#include <bits/stdc++.h>
using namespace std;

int main(void) {
	int n, m;
	cin >> n >> m;

	vector<vector<int> > e(n);
	vector<int> out(n, 0);
	int x, y, sz, cur;
	for (int i = 0; i < m; i++) {
		cin >> x >> y;
		e[y - 1].push_back(x - 1);
		out[x - 1]++;
	}

	queue<int>que;
	int ans = n;

	for (int i = 0; i < n; i++)if (out[i] == 0)que.push(i);
	while (!que.empty()) {
		ans--;
		cur = que.front();
		que.pop();
		sz = e[cur].size();
		for (int i = 0; i < sz; i++) {
			out[e[cur][i]]--;
			if (out[e[cur][i]] == 0)que.push(e[cur][i]);
		}
	}
	cout << ans << endl;
	return 0;
}

#include<bits/stdc++.h>
#include<atcoder/all>
using namespace std;
using namespace atcoder;
int main(){
	int n,m;
	cin >> n >> m;
	scc_graph g(n);
	vector<vector<int>>G(n);
	for(int i=0;i<m;i++){
		int u,v;
		cin >> u >> v;
		u--,v--;
		g.add_edge(u,v);
		G[u].push_back(v);
	}

	vector<vector<int>> scc=g.scc();
	int k=scc.size();
	vector<int> idx(n);
	for(int i=0;i<k;i++)for(auto v:scc[i])idx[v]=i;

	vector<int>dp(k);
	int ans=0;
	for(int i=k-1;i>=0;i--){
		if(scc[i].size()==1){
			for(auto v:G[scc[i][0]])dp[i]|=dp[idx[v]];
		}else{
			dp[i]=1;
		}
		if(dp[i])ans+=scc[i].size();
	}

	cout << ans << endl;
}
